import{_ as s,o as i,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const n="/testing-validation-guide/01-test-verify-validate.svg",e="/testing-validation-guide/02-test-layers.svg",r="/testing-validation-guide/03-test-case-anatomy.svg",p="/testing-validation-guide/04-risk-based-testing.svg",d="/testing-validation-guide/05-test-environment.svg",h="/testing-validation-guide/06-sil-hil-system.svg",o="/testing-validation-guide/07-remote-network-bench.svg",c="/testing-validation-guide/08-traceability-release.svg",_=JSON.parse('{"title":"软件测试与验证生产级手册","description":"从“为什么要测”讲到“怎样判断可以发布”，覆盖单元、契约、集成、系统、性能、故障注入、SIL/HIL、测试机和远程手术验证证据。","frontmatter":{"title":"软件测试与验证生产级手册","description":"从“为什么要测”讲到“怎样判断可以发布”，覆盖单元、契约、集成、系统、性能、故障注入、SIL/HIL、测试机和远程手术验证证据。","date":"2026-08-14T00:00:00.000Z","aside":false,"tags":["软件测试","验证与确认","质量工程","HIL","远程手术"]},"headers":[],"relativePath":"软件测试与验证生产级手册.md","filePath":"软件测试与验证生产级手册.md","lastUpdated":1786770226000}'),b={name:"软件测试与验证生产级手册.md"};function u(m,a,k,g,q,v){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="软件测试与验证生产级手册" tabindex="-1">软件测试与验证生产级手册 <a class="header-anchor" href="#软件测试与验证生产级手册" aria-label="Permalink to &quot;软件测试与验证生产级手册&quot;">​</a></h1><p>很多团队说自己“有测试”，实际情况可能是：开发者跑过几个单元测试，测试人员按界面点了一遍，CI 页面也是绿色的。可一上线，问题还是出现了。</p><p>原因通常不是大家不认真，而是一开始就没说清楚三件事：</p><ol><li>这个版本最怕出什么事？</li><li>哪种测试能够发现这种问题？</li><li>看到什么证据，我们才敢让它进入生产？</li></ol><p>这份手册就围绕这三个问题展开。它不追求把测试术语讲全，而是帮助团队做出靠谱的测试决定。</p><h2 id="先看一个例子" tabindex="-1">先看一个例子 <a class="header-anchor" href="#先看一个例子" aria-label="Permalink to &quot;先看一个例子&quot;">​</a></h2><p>假设远程手术系统修改了网络恢复逻辑：断网后重新连通，系统先同步主从状态，等医生确认后才允许远程操作。</p><p>开发者写了一个单元测试，证明 <code>network_recovered=true</code> 时状态机会进入“等待确认”。这当然有用，但还远远不够：</p><ul><li>如果旧控制台不认识新状态，会发生什么？</li><li>网络在恢复瞬间反复抖动，状态机会不会来回跳？</li><li>医生确认前，远程主手的指令是否真的到不了从手？</li><li>进程重启、时钟漂移或消息乱序后，系统还记得自己正在等待确认吗？</li><li>UI 显示“等待确认”时，底层控制权是否与画面一致？</li><li>真实设备上，从手有没有轻微跳动？</li><li>十次断网恢复是否都得到同样结果？</li></ul><p>单元测试回答的是一个很小的问题。发布决定需要把代码、服务、网络、设备和人的操作连起来看。</p><hr><h2 id="_1-测试、验证和确认到底有什么区别" tabindex="-1">1. 测试、验证和确认到底有什么区别 <a class="header-anchor" href="#_1-测试、验证和确认到底有什么区别" aria-label="Permalink to &quot;1. 测试、验证和确认到底有什么区别&quot;">​</a></h2><p>日常沟通里，这三个词经常混用。为了让研发、测试、产品和质量团队能说同一种语言，可以这样理解。</p><h3 id="测试-主动找证据" tabindex="-1">测试：主动找证据 <a class="header-anchor" href="#测试-主动找证据" aria-label="Permalink to &quot;测试：主动找证据&quot;">​</a></h3><p>测试是一种具体活动。给系统输入、制造条件、观察输出，然后与预期比较。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前置状态 + 输入/扰动 → 被测对象 → 可观察结果 → 与预期比较</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>测试不一定要运行完整软件。代码评审、静态分析、接口契约检查和模型检查，也能提供缺陷证据，只是观察方式不同。</p><h3 id="验证-东西有没有按设计做出来" tabindex="-1">验证：东西有没有按设计做出来 <a class="header-anchor" href="#验证-东西有没有按设计做出来" aria-label="Permalink to &quot;验证：东西有没有按设计做出来&quot;">​</a></h3><p>验证回答的是：“我们做出来的东西，是否满足已经写下来的要求和设计？”</p><p>例如，需求规定网络中断后 100 ms 内禁止远程指令继续生效。验证需要证明：在声明的设备、版本和网络条件下，这个时间要求确实满足。</p><h3 id="确认-做出来的东西是不是用户真正需要的" tabindex="-1">确认：做出来的东西是不是用户真正需要的 <a class="header-anchor" href="#确认-做出来的东西是不是用户真正需要的" aria-label="Permalink to &quot;确认：做出来的东西是不是用户真正需要的&quot;">​</a></h3><p>确认回答的是：“即使每条设计要求都满足，这套东西在真实使用场景里是否合适？”</p><p>例如，系统能在 100 ms 内停止远程控制，但告警信息让医生误以为设备已经故障，现场频繁采取不必要的急停。这可能通过了技术验证，却没有通过使用场景确认。</p><p>简单说：</p><table tabindex="0"><thead><tr><th>问题</th><th>更接近哪类活动</th></tr></thead><tbody><tr><td>函数是否正确处理空输入</td><td>测试 / 验证</td></tr><tr><td>服务是否满足接口协议</td><td>验证</td></tr><tr><td>整机是否满足性能指标</td><td>验证</td></tr><tr><td>医生能否正确理解网络告警</td><td>确认</td></tr><tr><td>整套远程操作流程是否适合临床场景</td><td>确认</td></tr></tbody></table><p>测试是拿证据的方法，验证和确认是要回答的问题。</p><p><a href="/testing-validation-guide/01-test-verify-validate.svg"><img src="'+n+'" alt="测试、验证与确认的关系"></a></p><p><em>图 1：测试是取得证据的动作；验证看“有没有按要求做对”，确认看“是不是用户真正需要的”。</em></p><hr><h2 id="_2-为什么不能只靠最后一次系统测试" tabindex="-1">2. 为什么不能只靠最后一次系统测试 <a class="header-anchor" href="#_2-为什么不能只靠最后一次系统测试" aria-label="Permalink to &quot;2. 为什么不能只靠最后一次系统测试&quot;">​</a></h2><p>系统测试最接近真实产品，但它并不适合发现所有问题。</p><p>假设一个状态机在某个边界条件下算错了。单元测试可能一秒钟就能指出具体分支；放到整机测试里，它可能要经过网络、消息队列、设备和 UI 才表现出来。此时你只能看到“从手没按预期停下”，定位成本高很多。</p><p>反过来也一样。单元测试全过，不能证明服务组合、真实驱动和现场网络没有问题。</p><p>所以测试要分层。每一层负责自己最擅长发现的问题：</p><table tabindex="0"><thead><tr><th>层级</th><th>主要检查什么</th><th>失败后通常找谁</th></tr></thead><tbody><tr><td>静态检查</td><td>明显错误、危险写法、依赖和密钥</td><td>对应代码作者</td></tr><tr><td>单元测试</td><td>函数、算法、状态转换和错误分支</td><td>模块开发者</td></tr><tr><td>组件测试</td><td>模块与数据库、文件、队列、驱动适配</td><td>组件负责人</td></tr><tr><td>契约测试</td><td>两端是否仍说同一种协议</td><td>接口双方</td></tr><tr><td>集成测试</td><td>多个真实组件组合后是否工作</td><td>系统集成负责人</td></tr><tr><td>系统测试</td><td>完整产品是否满足系统要求</td><td>测试与系统团队</td></tr><tr><td>确认测试</td><td>真实用户和场景是否可接受</td><td>产品、临床与质量团队</td></tr></tbody></table><p>不要迷信测试金字塔的具体形状。有硬件、网络和实时控制的系统，集成测试和 HIL 本来就会比普通 Web 项目更重。真正需要保持的是：便宜、快速、容易定位的测试尽量多跑；昂贵、接近真实环境的测试用来覆盖组合风险和最终证据。</p><p><a href="/testing-validation-guide/02-test-layers.svg"><img src="'+e+`" alt="不同测试层级的作用与成本"></a></p><p><em>图 2：底层测试负责快速反馈，上层测试负责真实组合和最终证据，两边不能互相替代。</em></p><hr><h2 id="_3-一条需求怎样变成测试" tabindex="-1">3. 一条需求怎样变成测试 <a class="header-anchor" href="#_3-一条需求怎样变成测试" aria-label="Permalink to &quot;3. 一条需求怎样变成测试&quot;">​</a></h2><p>先看一句很常见的要求：</p><blockquote><p>网络异常时，系统应及时告警并保证机器人安全。</p></blockquote><p>这句话方向正确，但没法直接测试。至少还缺少：</p><ul><li>什么叫网络异常：RTT、丢包、抖动还是完全断开？</li><li>“及时”是多少毫秒？从哪个事件开始计时？</li><li>哪个界面告警，告警内容是什么？</li><li>“保证安全”具体要求从手停止、保持位置，还是控制权返回本地？</li><li>网络恢复后能否自动继续？是否需要医生确认？</li><li>哪些设备和软件版本属于测试范围？</li></ul><p>把它改写成可验证要求，可能是：</p><blockquote><p>当控制链连续 300 ms 未收到有效数据包时，患者侧控制器应在 100 ms 内进入安全保持状态；远程指令不得继续驱动从手；系统应记录异常时间、状态变化和控制权归属。网络恢复并完成状态同步后，只有医生确认才能重新允许远程控制。</p></blockquote><p>然后再拆成测试：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求</span></span>
<span class="line"><span>├── 断网检测时间测试</span></span>
<span class="line"><span>├── 安全保持状态测试</span></span>
<span class="line"><span>├── 远程指令隔离测试</span></span>
<span class="line"><span>├── 告警显示测试</span></span>
<span class="line"><span>├── 审计日志完整性测试</span></span>
<span class="line"><span>├── 网络恢复与状态同步测试</span></span>
<span class="line"><span>└── 医生确认前后权限测试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>一个好测试不是“点一下看看对不对”，而是包含以下要素：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NET-RECOVERY-008</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">purpose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">验证网络恢复后不会自动恢复远程运动控制</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">preconditions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">远程端已经获得控制权</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">系统版本和设备配置已经记录</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stimulus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">中断控制链 3 秒后恢复</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">observations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">控制权状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">从手位置和速度</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">UI 提示</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">事件日志</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">expected</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">医生确认前远程指令不引起从手运动</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">确认后才重新允许操作</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">evidence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">状态日志</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">运动测量记录</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">测试设备原始数据</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">repeat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>这里最重要的不是 YAML 格式，而是目的、条件、刺激、观察量、预期和证据都写清楚。</p><p><a href="/testing-validation-guide/03-test-case-anatomy.svg"><img src="`+r+'" alt="一条完整测试用例的组成"></a></p><p><em>图 3：测试用例不是一串操作步骤；缺少观察量、预期或证据，就很难复现和审查。</em></p><hr><h2 id="_4-测多少才算够" tabindex="-1">4. 测多少才算够 <a class="header-anchor" href="#_4-测多少才算够" aria-label="Permalink to &quot;4. 测多少才算够&quot;">​</a></h2><p>不存在一个通用数字。覆盖率达到 90%，也可能没有测试真正危险的路径；系统测试跑了 500 条，也可能遗漏一次网络恢复和状态同步的竞争条件。</p><p>更实用的办法是按风险决定测试力度。</p><h3 id="先看失败后果" tabindex="-1">先看失败后果 <a class="header-anchor" href="#先看失败后果" aria-label="Permalink to &quot;先看失败后果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失败后果</th><th>测试策略</th></tr></thead><tbody><tr><td>页面文字显示错误</td><td>常规功能测试即可</td></tr><tr><td>用户需要重试，但数据不丢</td><td>增加异常路径和恢复测试</td></tr><tr><td>造成数据损坏或长时间停机</td><td>增加故障注入、备份恢复和长稳测试</td></tr><tr><td>可能导致非预期运动或临床风险</td><td>独立验证、边界测试、SIL/HIL、重复性和安全状态证据</td></tr></tbody></table><h3 id="再看变更影响面" tabindex="-1">再看变更影响面 <a class="header-anchor" href="#再看变更影响面" aria-label="Permalink to &quot;再看变更影响面&quot;">​</a></h3><p>同样是一行代码，风险可能完全不同：</p><ul><li>修改日志文案，影响面小；</li><li>修改公共协议字段，会影响新旧版本组合；</li><li>修改控制权状态机，会影响网络、UI、控制器和临床操作；</li><li>修改 bootloader，会影响升级失败后的恢复能力。</li></ul><p>可以给每次变更做一张简短影响表：</p><table tabindex="0"><thead><tr><th>维度</th><th>要问的问题</th></tr></thead><tbody><tr><td>功能</td><td>哪些用户流程会变化？</td></tr><tr><td>接口</td><td>哪些上下游和旧版本会受影响？</td></tr><tr><td>数据</td><td>是否改变格式、迁移或保留方式？</td></tr><tr><td>环境</td><td>Windows、Linux、Docker、硬件型号是否都受影响？</td></tr><tr><td>性能</td><td>延迟、吞吐、CPU、内存和控制周期会变化吗？</td></tr><tr><td>安全</td><td>权限、加密、日志和攻击面是否变化？</td></tr><tr><td>恢复</td><td>旧版本还能否运行？失败后如何回到安全状态？</td></tr></tbody></table><p>测试充分性的判断，来自“重要风险都有对应证据”，而不是测试数量看起来很多。</p><p><a href="/testing-validation-guide/04-risk-based-testing.svg"><img src="'+p+'" alt="按风险决定测试投入"></a></p><p><em>图 4：失败后果越严重、变更影响面越大，测试就越要接近真实环境，并保留更完整的证据。</em></p><hr><h2 id="_5-一套实用的测试分层" tabindex="-1">5. 一套实用的测试分层 <a class="header-anchor" href="#_5-一套实用的测试分层" aria-label="Permalink to &quot;5. 一套实用的测试分层&quot;">​</a></h2><h3 id="_5-1-静态检查" tabindex="-1">5.1 静态检查 <a class="header-anchor" href="#_5-1-静态检查" aria-label="Permalink to &quot;5.1 静态检查&quot;">​</a></h3><p>程序还没运行，就可以检查：</p><ul><li>编译器告警；</li><li>格式、lint、类型错误；</li><li>C/C++ 未定义行为和危险 API；</li><li>依赖漏洞、许可证和密钥泄露；</li><li>配置 schema、接口描述和生成代码是否一致。</li></ul><p>静态检查便宜、稳定，适合每次提交都跑。但它只能发现“看得出来”的问题，不能代替运行时测试。</p><h3 id="_5-2-单元测试" tabindex="-1">5.2 单元测试 <a class="header-anchor" href="#_5-2-单元测试" aria-label="Permalink to &quot;5.2 单元测试&quot;">​</a></h3><p>单元测试适合算法、状态机、校验规则、错误处理和边界条件。</p><p>好的单元测试有三个特点：</p><ul><li>很快，开发者愿意经常运行；</li><li>失败时能直接指出哪条业务规则被破坏；</li><li>不依赖真实网络、数据库和共享测试机。</li></ul><p>不要把实现细节全部 mock 掉。测试应关注可观察行为，否则稍微重构就会大面积失败，却没有发现真实缺陷。</p><h3 id="_5-3-组件测试" tabindex="-1">5.3 组件测试 <a class="header-anchor" href="#_5-3-组件测试" aria-label="Permalink to &quot;5.3 组件测试&quot;">​</a></h3><p>组件测试允许一个服务或模块使用真实数据库、文件系统、消息队列或协议模拟器，但不启动完整产品。</p><p>例如测试云转发服务时，可以启动真实 PostgreSQL 和消息队列，用假的机器人端发送协议消息。这样既能发现序列化、事务和重试问题，又比整套设备测试容易定位。</p><h3 id="_5-4-契约测试" tabindex="-1">5.4 契约测试 <a class="header-anchor" href="#_5-4-契约测试" aria-label="Permalink to &quot;5.4 契约测试&quot;">​</a></h3><p>远程手术系统经常需要新旧版本共存。契约测试检查的不是“接口能不能返回 200”，而是双方是否仍理解相同语义：</p><ul><li>字段增加后旧版本是否能忽略；</li><li>枚举增加后旧端如何处理未知值；</li><li>超时和错误码是否仍有一致含义；</li><li>消息顺序、幂等键和重试规则是否一致；</li><li>云、边、端各版本组合是否在支持矩阵内。</li></ul><p>接口变更先过契约测试，再进入昂贵的整机测试。</p><h3 id="_5-5-集成和系统测试" tabindex="-1">5.5 集成和系统测试 <a class="header-anchor" href="#_5-5-集成和系统测试" aria-label="Permalink to &quot;5.5 集成和系统测试&quot;">​</a></h3><p>集成测试关注组件连接处，系统测试关注完整产品行为。两者需要真实或接近真实的部署环境，并记录：</p><ul><li>软件、固件和配置版本；</li><li>OS、驱动、数据库和容器版本；</li><li>网络拓扑和外部依赖；</li><li>测试数据和设备编号；</li><li>原始日志、测量数据和测试结论。</li></ul><p>如果失败后无法重建这些条件，这次测试很难成为可靠证据。</p><h3 id="_5-6-确认测试" tabindex="-1">5.6 确认测试 <a class="header-anchor" href="#_5-6-确认测试" aria-label="Permalink to &quot;5.6 确认测试&quot;">​</a></h3><p>确认测试尽量贴近用户实际工作。它关心的不只是功能是否存在，还包括：</p><ul><li>操作者能否理解状态和告警；</li><li>紧急情况下是否知道下一步做什么；</li><li>工作流是否增加不合理负担；</li><li>自动化是否让人错误地高估系统能力；</li><li>降级和恢复行为是否符合临床预期。</li></ul><p>涉及真实用户、临床流程或人因的结论，不应由开发团队自己代替用户下结论。</p><hr><h2 id="_6-测试机应该怎样建设" tabindex="-1">6. 测试机应该怎样建设 <a class="header-anchor" href="#_6-测试机应该怎样建设" aria-label="Permalink to &quot;6. 测试机应该怎样建设&quot;">​</a></h2><p>测试机不是一台“大家都可以上去改”的共享电脑。它是一个需要版本和配置管理的实验环境。</p><p><a href="/testing-validation-guide/05-test-environment.svg"><img src="'+d+`" alt="生产级测试环境结构"></a></p><p><em>图 5：Windows、Linux、Docker 和实验室环境各有任务，但版本、配置、日志和报告要统一管理。</em></p><h3 id="测试机至少记录什么" tabindex="-1">测试机至少记录什么 <a class="header-anchor" href="#测试机至少记录什么" aria-label="Permalink to &quot;测试机至少记录什么&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机器身份</span></span>
<span class="line"><span>├── 资产编号、位置、负责人</span></span>
<span class="line"><span>├── OS 版本和补丁</span></span>
<span class="line"><span>├── CPU、内存、GPU、网卡</span></span>
<span class="line"><span>├── 驱动、运行时和安全软件</span></span>
<span class="line"><span>├── 当前应用/固件版本</span></span>
<span class="line"><span>├── 当前配置版本</span></span>
<span class="line"><span>└── 最近一次环境校验时间</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="测试机和生产机应该多像" tabindex="-1">测试机和生产机应该多像 <a class="header-anchor" href="#测试机和生产机应该多像" aria-label="Permalink to &quot;测试机和生产机应该多像&quot;">​</a></h3><p>不需要一模一样，但与测试结论有关的差异必须知道。</p><table tabindex="0"><thead><tr><th>项目</th><th>建议</th></tr></thead><tbody><tr><td>OS 和运行时</td><td>与目标生产版本一致或进入明确兼容矩阵</td></tr><tr><td>网络策略</td><td>复刻端口、证书、代理和防火墙限制</td></tr><tr><td>数据</td><td>使用构造或脱敏数据，不复制真实敏感信息</td></tr><tr><td>账号权限</td><td>模拟生产最小权限，不长期使用管理员运行</td></tr><tr><td>外部依赖</td><td>能用真实测试实例就不用永远成功的假服务</td></tr><tr><td>可破坏性</td><td>允许断网、停服务、磁盘满和回滚演练</td></tr></tbody></table><h3 id="防止测试机慢慢-变脏" tabindex="-1">防止测试机慢慢“变脏” <a class="header-anchor" href="#防止测试机慢慢-变脏" aria-label="Permalink to &quot;防止测试机慢慢“变脏”&quot;">​</a></h3><ul><li>环境安装尽量脚本化；</li><li>测试开始前执行环境自检；</li><li>禁止无记录地手工安装依赖；</li><li>定期从基线镜像重建；</li><li>测试结束后清理临时数据和账号；</li><li>发现环境漂移时让测试失败，而不是临时改机器把它跑通。</li></ul><hr><h2 id="_7-windows、linux-和-docker-分别要测什么" tabindex="-1">7. Windows、Linux 和 Docker 分别要测什么 <a class="header-anchor" href="#_7-windows、linux-和-docker-分别要测什么" aria-label="Permalink to &quot;7. Windows、Linux 和 Docker 分别要测什么&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>除了业务功能，还要关注：</p><ul><li>安装、静默安装、升级、卸载和重启；</li><li>Windows Service 的账号、启动顺序和恢复策略；</li><li>中文路径、长路径、文件锁和杀毒软件影响；</li><li>普通用户权限、UAC、防火墙和证书存储；</li><li>不同 Windows 版本、补丁和 Visual C++ Runtime；</li><li>安装包签名与文件完整性。</li></ul><p>一份只在管理员桌面会话里运行过的程序，还不能说明它能作为生产服务稳定运行。</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>重点包括：</p><ul><li>发行版、glibc、内核和 CPU 架构；</li><li>systemd 启停、重启、超时和资源限制；</li><li>非 root 用户、文件权限、SELinux/AppArmor；</li><li>日志轮转、磁盘满和只读文件系统；</li><li><code>.deb</code>、<code>.rpm</code> 或 tar 包升级和配置保留；</li><li>时钟同步、DNS、证书和网络中断。</li></ul><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><p>镜像构建成功只是第一步，还要测试：</p><ul><li>容器是否使用非 root 用户；</li><li>只读根文件系统和临时目录是否够用；</li><li>健康检查能否反映真实就绪状态；</li><li>收到停止信号后是否能正常退出；</li><li>CPU、内存和磁盘限制下是否仍可控；</li><li>数据卷和数据库能否跨版本使用；</li><li>旧镜像回退后是否仍能读取现有数据；</li><li>镜像摘要、SBOM 和漏洞扫描是否完整。</li></ul><p>跨平台测试不要复制三套业务用例。把业务规则放在共享测试层，再为 Windows Service、systemd 和 Docker 生命周期补各自的适配测试。</p><hr><h2 id="_8-自动化测试怎样接入-ci-cd" tabindex="-1">8. 自动化测试怎样接入 CI/CD <a class="header-anchor" href="#_8-自动化测试怎样接入-ci-cd" aria-label="Permalink to &quot;8. 自动化测试怎样接入 CI/CD&quot;">​</a></h2><p>测试代码应与产品代码一起评审，测试入口应能在本地和 CI 中使用同一条命令。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ci/</span></span>
<span class="line"><span>├── lint.ps1 / lint.sh</span></span>
<span class="line"><span>├── unit-test.ps1 / unit-test.sh</span></span>
<span class="line"><span>├── component-test.ps1 / component-test.sh</span></span>
<span class="line"><span>├── package.ps1 / package.sh</span></span>
<span class="line"><span>└── collect-evidence.ps1 / collect-evidence.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>流水线只负责安排顺序和机器，测试逻辑不要全部塞进 GitHub Actions 或 <code>.gitlab-ci.yml</code>。</p><p>推荐把测试分成三个时间档：</p><table tabindex="0"><thead><tr><th>时间档</th><th>目标时长</th><th>内容</th><th>什么时候跑</th></tr></thead><tbody><tr><td>快</td><td>5～10 分钟</td><td>静态检查、单元、少量组件测试</td><td>每次 PR/MR</td></tr><tr><td>中</td><td>20～40 分钟</td><td>完整组件、契约、安装和集成</td><td>主干、候选版本</td></tr><tr><td>慢</td><td>数小时以上</td><td>长稳、性能、HIL、故障注入</td><td>夜间、周末、正式发布前</td></tr></tbody></table><p>慢测试不是不重要，而是不应让每个小提交都排队等两小时。快测试先挡住大多数问题，慢测试提供更接近生产的证据。</p><p>测试报告至少保留：</p><ul><li>commit SHA 和制品摘要；</li><li>测试套件与用例版本；</li><li>环境和设备版本；</li><li>通过、失败、跳过和未执行数量；</li><li>原始日志与关键测量；</li><li>重试记录；</li><li>负责人签署的发布结论。</li></ul><p>具体流水线与 Runner 配置参见 <a href="/CI-CD生产级使用手册.html">CI/CD 生产级使用手册</a>。</p><hr><h2 id="_9-测试数据不能随便准备" tabindex="-1">9. 测试数据不能随便准备 <a class="header-anchor" href="#_9-测试数据不能随便准备" aria-label="Permalink to &quot;9. 测试数据不能随便准备&quot;">​</a></h2><p>测试数据经常被低估。很多“偶现问题”其实来自数据状态不受控。</p><h3 id="数据分四类管理" tabindex="-1">数据分四类管理 <a class="header-anchor" href="#数据分四类管理" aria-label="Permalink to &quot;数据分四类管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>用途</th><th>注意事项</th></tr></thead><tbody><tr><td>固定夹具</td><td>单元和组件测试</td><td>小、可读、随代码版本化</td></tr><tr><td>合成数据</td><td>系统、性能、边界场景</td><td>能构造极端和错误情况</td></tr><tr><td>脱敏数据</td><td>验证真实分布</td><td>需要审批、去标识和访问控制</td></tr><tr><td>运行时采样</td><td>回归问题复现</td><td>不直接把生产隐私数据复制进 CI</td></tr></tbody></table><h3 id="好的测试数据应满足" tabindex="-1">好的测试数据应满足 <a class="header-anchor" href="#好的测试数据应满足" aria-label="Permalink to &quot;好的测试数据应满足&quot;">​</a></h3><ul><li>知道它从哪里来；</li><li>能重复生成；</li><li>有版本和校验值；</li><li>包含正常、边界、错误和历史缺陷样本；</li><li>不包含不必要的患者和个人信息；</li><li>测试结束后有保留或销毁规则。</li></ul><p>对 AI 和机器人学习，数据本身还要记录采集设备、标注版本、场景分布和排除条件，否则模型回归很难解释。</p><hr><h2 id="_10-性能测试不是只压一个最大并发" tabindex="-1">10. 性能测试不是只压一个最大并发 <a class="header-anchor" href="#_10-性能测试不是只压一个最大并发" aria-label="Permalink to &quot;10. 性能测试不是只压一个最大并发&quot;">​</a></h2><p>性能至少有四类问题：</p><h3 id="基准测试" tabindex="-1">基准测试 <a class="header-anchor" href="#基准测试" aria-label="Permalink to &quot;基准测试&quot;">​</a></h3><p>在固定环境下记录当前版本的延迟、吞吐、CPU、内存和磁盘，作为以后比较的基线。</p><h3 id="负载测试" tabindex="-1">负载测试 <a class="header-anchor" href="#负载测试" aria-label="Permalink to &quot;负载测试&quot;">​</a></h3><p>在预计正常和高峰负载下运行，确认系统仍满足目标。</p><h3 id="压力测试" tabindex="-1">压力测试 <a class="header-anchor" href="#压力测试" aria-label="Permalink to &quot;压力测试&quot;">​</a></h3><p>继续增加负载，找到系统从哪里开始恶化，以及恶化时能否保持可控，而不是追求一个漂亮的峰值数字。</p><h3 id="长稳测试" tabindex="-1">长稳测试 <a class="header-anchor" href="#长稳测试" aria-label="Permalink to &quot;长稳测试&quot;">​</a></h3><p>连续运行数小时或数天，观察内存增长、句柄泄漏、线程积压、日志膨胀、证书刷新和网络重连。</p><p>性能报告必须说明硬件、版本、数据规模、预热方式、并发模型和统计口径。平均延迟通常会掩盖少量严重卡顿，生产判断应同时看 p95、p99、最大值和超时比例。</p><p>对实时控制，还要关注控制周期 deadline miss、尾延迟、抖动和停止响应，不能只看平均 RTT。</p><hr><h2 id="_11-故障注入-确认系统真的会安全失败" tabindex="-1">11. 故障注入：确认系统真的会安全失败 <a class="header-anchor" href="#_11-故障注入-确认系统真的会安全失败" aria-label="Permalink to &quot;11. 故障注入：确认系统真的会安全失败&quot;">​</a></h2><p>故障注入不是随机把服务弄坏，而是针对设计里的恢复假设做实验。</p><p>可以从这些场景开始：</p><ul><li>网络延迟、抖动、丢包、乱序和完全中断；</li><li>DNS、证书、时间同步和身份服务不可用；</li><li>数据库连接耗尽、慢查询和主备切换；</li><li>磁盘满、目录只读、日志写入失败；</li><li>进程崩溃、机器重启和容器反复拉起；</li><li>NAS 不可达、制品下载中断和校验失败；</li><li>消息重复、延迟到达和顺序颠倒；</li><li>设备掉电、驱动异常和传感器数据冻结。</li></ul><p>每个实验都要提前写：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们破坏什么？</span></span>
<span class="line"><span>预计系统如何发现？</span></span>
<span class="line"><span>应该进入什么安全状态？</span></span>
<span class="line"><span>用户会看到什么？</span></span>
<span class="line"><span>如何确认没有数据或控制指令继续泄漏？</span></span>
<span class="line"><span>恢复需要自动完成还是人工确认？</span></span>
<span class="line"><span>什么条件下立即停止实验？</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>不要第一次在生产上尝试故障注入。先从组件和测试环境开始，确认监控、停止条件和恢复动作可靠，再讨论更接近生产的演练。</p><hr><h2 id="_12-sil-与-hil-怎么分工" tabindex="-1">12. SIL 与 HIL 怎么分工 <a class="header-anchor" href="#_12-sil-与-hil-怎么分工" aria-label="Permalink to &quot;12. SIL 与 HIL 怎么分工&quot;">​</a></h2><h3 id="sil-先把大量组合跑起来" tabindex="-1">SIL：先把大量组合跑起来 <a class="header-anchor" href="#sil-先把大量组合跑起来" aria-label="Permalink to &quot;SIL：先把大量组合跑起来&quot;">​</a></h3><p>软件在环（SIL）用仿真器或模拟对象代替真实硬件，适合：</p><ul><li>状态机和控制算法的大量参数组合；</li><li>极端场景和难以稳定复现的故障；</li><li>每次提交后的快速回归；</li><li>确认一个问题属于软件逻辑，而不是台架接线。</li></ul><p>SIL 的弱点也很明显：仿真器不会自动包含真实驱动、时钟、噪声、摩擦、机械间隙和硬件故障。</p><h3 id="hil-验证软件和真实硬件能否一起工作" tabindex="-1">HIL：验证软件和真实硬件能否一起工作 <a class="header-anchor" href="#hil-验证软件和真实硬件能否一起工作" aria-label="Permalink to &quot;HIL：验证软件和真实硬件能否一起工作&quot;">​</a></h3><p>硬件在环（HIL）把真实控制器、接口板、驱动或设备接入测试闭环，适合：</p><ul><li>驱动和通信时序；</li><li>控制周期、急停和安全状态；</li><li>电源、掉线和重启行为；</li><li>固件与硬件 revision 兼容；</li><li>SIL 无法准确描述的物理响应。</li></ul><p>HIL 台架也需要管理：接线图、仪器编号、校准状态、固件版本、采样率、同步方法和原始数据缺一不可。</p><p>比较合理的路径是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单元测试 → SIL 大量回归 → HIL 关键路径 → 整机确认</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不要把所有组合都留给昂贵的 HIL，也不要用仿真结果替代真实硬件证据。</p><p><a href="/testing-validation-guide/06-sil-hil-system.svg"><img src="`+h+'" alt="SIL、HIL 与整机测试分工"></a></p><p><em>图 6：先用便宜的测试扫过大量组合，再把硬件特性和高风险场景留给 HIL 与整机确认。</em></p><hr><h2 id="_13-远程手术网络怎样测" tabindex="-1">13. 远程手术网络怎样测 <a class="header-anchor" href="#_13-远程手术网络怎样测" aria-label="Permalink to &quot;13. 远程手术网络怎样测&quot;">​</a></h2><p>网络测试最容易犯的错误，是只在某个办公室网络里跑一次，然后记录“延迟正常”。</p><p><a href="/testing-validation-guide/07-remote-network-bench.svg"><img src="'+o+`" alt="远程手术网络测试台架"></a></p><p><em>图 7：网络指标只是条件；最终还要独立观察控制、安全行为和使用者能否正确理解系统状态。</em></p><p>一套可重复的网络测试至少需要三类设备或软件：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>医生端系统</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── 独立时间与流量测量</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>网络损伤设备：带宽 / RTT / 抖动 / 丢包 / 乱序 / 中断</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── 系统自身监测值</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>患者端机器人与本地控制单元</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>独立测量很重要。系统不能一边声明“自己测到 RTT 正常”，一边又只用自己的数值证明自己正确。</p><h3 id="至少覆盖四组条件" tabindex="-1">至少覆盖四组条件 <a class="header-anchor" href="#至少覆盖四组条件" aria-label="Permalink to &quot;至少覆盖四组条件&quot;">​</a></h3><ol><li><strong>典型条件</strong>：建立正常基线；</li><li><strong>声明边界</strong>：把主要参数放到最低允许值；</li><li><strong>越界条件</strong>：确认告警、限制和安全状态；</li><li><strong>恢复过程</strong>：确认状态同步和人工确认，不自动恢复危险动作。</li></ol><h3 id="不要只看网络指标" tabindex="-1">不要只看网络指标 <a class="header-anchor" href="#不要只看网络指标" aria-label="Permalink to &quot;不要只看网络指标&quot;">​</a></h3><p>最终要观察网络变化对系统行为的影响：</p><ul><li>主从启动、跟随和停止延迟；</li><li>从手位置、速度、抖动和非预期运动；</li><li>视频冻结、花屏和有效帧；</li><li>网络状态判定时间；</li><li>告警显示和控制权变化；</li><li>医生确认前后的指令隔离；</li><li>日志时间线能否重建全过程。</li></ul><p>阈值应来自产品技术要求、风险分析和实际测量。本手册不替具体产品指定 RTT、丢包率或重复次数。</p><hr><h2 id="_14-安全测试要从需求开始" tabindex="-1">14. 安全测试要从需求开始 <a class="header-anchor" href="#_14-安全测试要从需求开始" aria-label="Permalink to &quot;14. 安全测试要从需求开始&quot;">​</a></h2><p>只在发布前做一次渗透测试，通常太晚。安全测试应分散到整个开发过程：</p><table tabindex="0"><thead><tr><th>阶段</th><th>可以做什么</th></tr></thead><tbody><tr><td>设计</td><td>威胁建模、信任边界、滥用场景</td></tr><tr><td>编码</td><td>静态分析、密钥扫描、依赖和许可证检查</td></tr><tr><td>组件</td><td>认证、授权、输入、加密和日志测试</td></tr><tr><td>集成</td><td>证书、网络分区、权限提升和接口攻击</td></tr><tr><td>系统</td><td>漏洞扫描、DAST、模糊测试、渗透测试</td></tr><tr><td>发布后</td><td>漏洞监测、补丁验证和事件响应演练</td></tr></tbody></table><p>渗透测试发现的是当时能被发现的问题，不是“系统从此安全”的证明。安全要求、测试用例、漏洞处置和修复回归需要长期维护。</p><p>Web/API 系统可以用 <a href="https://owasp.org/www-project-application-security-verification-standard/" target="_blank" rel="noreferrer">OWASP ASVS</a> 帮助建立验证清单；安全开发流程可参考 <a href="https://csrc.nist.gov/pubs/sp/800/218/final" target="_blank" rel="noreferrer">NIST SSDF</a>。</p><hr><h2 id="_15-覆盖率怎么看才不被骗" tabindex="-1">15. 覆盖率怎么看才不被骗 <a class="header-anchor" href="#_15-覆盖率怎么看才不被骗" aria-label="Permalink to &quot;15. 覆盖率怎么看才不被骗&quot;">​</a></h2><p>覆盖率说明哪些代码被执行过，不说明结果是否被认真验证。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行了 if 分支          ≠ 检查了正确结果</span></span>
<span class="line"><span>行覆盖率达到 90%        ≠ 风险覆盖达到 90%</span></span>
<span class="line"><span>所有测试通过            ≠ 没有跳过重要测试</span></span>
<span class="line"><span>系统跑了 24 小时        ≠ 观察到了关键资源和异常</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>覆盖率适合做这些事：</p><ul><li>找完全没被测试的模块；</li><li>检查新增代码是否有基本测试；</li><li>发现关键错误分支没有执行；</li><li>观察覆盖率突然下降。</li></ul><p>不要为了数字写没有断言价值的测试。对安全状态机、权限判断、协议解析和恢复逻辑，应额外看分支覆盖、条件覆盖、边界值和变异测试。</p><hr><h2 id="_16-不稳定测试怎么处理" tabindex="-1">16. 不稳定测试怎么处理 <a class="header-anchor" href="#_16-不稳定测试怎么处理" aria-label="Permalink to &quot;16. 不稳定测试怎么处理&quot;">​</a></h2><p>同一代码有时通过、有时失败，会迅速消耗团队对测试的信任。常见原因包括：</p><ul><li>依赖真实时间和固定等待；</li><li>测试之间共享数据或端口；</li><li>并行执行时资源竞争；</li><li>外部服务、网络和测试机状态不稳定；</li><li>随机数没有记录种子；</li><li>异步事件没有明确完成条件。</li></ul><p>处理方法不是“失败就重跑三次然后算通过”。重试可以帮助收集信息，但最终报告必须保留首次失败。</p><p>建议记录：</p><table tabindex="0"><thead><tr><th>指标</th><th>作用</th></tr></thead><tbody><tr><td>首次通过率</td><td>发现被重试掩盖的问题</td></tr><tr><td>不稳定用例数量</td><td>观察测试健康度</td></tr><tr><td>隔离时间</td><td>防止坏测试永久留在隔离区</td></tr><tr><td>平均定位时间</td><td>判断测试是否容易诊断</td></tr><tr><td>按环境分类的失败</td><td>区分产品缺陷和基础设施问题</td></tr></tbody></table><p>不稳定测试应有负责人和修复期限。长期直接跳过，相当于悄悄拆掉质量门。</p><hr><h2 id="_17-怎样形成可追溯证据" tabindex="-1">17. 怎样形成可追溯证据 <a class="header-anchor" href="#_17-怎样形成可追溯证据" aria-label="Permalink to &quot;17. 怎样形成可追溯证据&quot;">​</a></h2><p>对普通互联网服务，追溯主要帮助事故定位；对医疗和安全关键软件，它还是设计控制和验证资料的一部分。</p><p>推荐建立双向关系：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户需要</span></span>
<span class="line"><span>  → 系统需求</span></span>
<span class="line"><span>  → 风险与控制措施</span></span>
<span class="line"><span>  → 软件/硬件设计</span></span>
<span class="line"><span>  → 测试用例</span></span>
<span class="line"><span>  → 测试结果与原始数据</span></span>
<span class="line"><span>  → 发布制品</span></span>
<span class="line"><span>  → 部署到哪些设备</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>反过来也要能查：某个测试失败会阻断哪些需求？某个设备正在运行的版本，使用了哪次测试结论？</p><p>最小追溯表可以这样设计：</p><table tabindex="0"><thead><tr><th>需求 ID</th><th>风险/控制</th><th>实现位置</th><th>测试 ID</th><th>结果</th><th>制品摘要</th></tr></thead><tbody><tr><td>SYS-NET-014</td><td>网络中断后禁止远程动作</td><td>control/state.cpp</td><td>NET-006/008</td><td>Pass</td><td>sha256:...</td></tr></tbody></table><p>追溯表不是最后补文档。需求和测试编号应在开发过程中就建立，否则发布前再补，很容易出现“表格有关系，实际测试没覆盖”的情况。</p><p><a href="/testing-validation-guide/08-traceability-release.svg"><img src="`+c+'" alt="从需求到发布决定的证据链"></a></p><p><em>图 8：关键需求要能找到验证结果，生产版本也要能反查批准它的完整证据。</em></p><hr><h2 id="_18-发布前测试结论应该怎么写" tabindex="-1">18. 发布前测试结论应该怎么写 <a class="header-anchor" href="#_18-发布前测试结论应该怎么写" aria-label="Permalink to &quot;18. 发布前测试结论应该怎么写&quot;">​</a></h2><p>“全部测试通过，可以发布”通常信息不够。</p><p>一份能支持决策的结论至少说明：</p><h3 id="测了什么" tabindex="-1">测了什么 <a class="header-anchor" href="#测了什么" aria-label="Permalink to &quot;测了什么&quot;">​</a></h3><ul><li>对应 commit 和制品摘要；</li><li>目标平台、配置和设备范围；</li><li>执行了哪些测试套件；</li><li>哪些风险和变更得到覆盖。</li></ul><h3 id="没测什么" tabindex="-1">没测什么 <a class="header-anchor" href="#没测什么" aria-label="Permalink to &quot;没测什么&quot;">​</a></h3><ul><li>因环境、时间或设备限制未执行的测试；</li><li>不在本版本范围内的平台和组合；</li><li>暂时接受的已知问题。</li></ul><h3 id="结果怎样" tabindex="-1">结果怎样 <a class="header-anchor" href="#结果怎样" aria-label="Permalink to &quot;结果怎样&quot;">​</a></h3><ul><li>通过、失败、跳过、不稳定和重试情况；</li><li>与上一版本相比的性能变化；</li><li>故障注入和回滚是否成功；</li><li>原始证据在哪里。</li></ul><h3 id="建议怎样发布" tabindex="-1">建议怎样发布 <a class="header-anchor" href="#建议怎样发布" aria-label="Permalink to &quot;建议怎样发布&quot;">​</a></h3><ul><li>是否可以进入测试、预生产或生产；</li><li>是否需要灰度、现场支持或非手术窗口；</li><li>观察哪些指标；</li><li>什么条件下停止或恢复旧版本。</li></ul><p>测试团队提供证据和建议，产品、研发、质量、运维和业务责任人共同承担发布决定。不能把所有风险都塞给最后签字的测试负责人。</p><hr><h2 id="_19-团队怎样分工" tabindex="-1">19. 团队怎样分工 <a class="header-anchor" href="#_19-团队怎样分工" aria-label="Permalink to &quot;19. 团队怎样分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>主要责任</th></tr></thead><tbody><tr><td>开发</td><td>单元和组件测试、可测试性设计、缺陷回归</td></tr><tr><td>测试</td><td>测试策略、系统验证、证据质量和独立判断</td></tr><tr><td>系统/架构</td><td>接口、故障模型、关键性能和环境边界</td></tr><tr><td>产品/临床</td><td>使用场景、可接受行为和确认活动</td></tr><tr><td>DevOps/SRE</td><td>测试环境、自动执行、观测和恢复演练</td></tr><tr><td>安全</td><td>威胁、攻击面、安全验证和漏洞闭环</td></tr><tr><td>质量/法规</td><td>流程、适用标准、追溯和正式批准</td></tr></tbody></table><p>测试不是测试部门的私事。代码难以隔离、接口没有契约、日志无法定位、环境不能重建，最后都会变成“测试效率低”。这些问题需要在设计阶段解决。</p><hr><h2 id="_20-从零开始的落地顺序" tabindex="-1">20. 从零开始的落地顺序 <a class="header-anchor" href="#_20-从零开始的落地顺序" aria-label="Permalink to &quot;20. 从零开始的落地顺序&quot;">​</a></h2><h3 id="第一阶段-先让测试可重复" tabindex="-1">第一阶段：先让测试可重复 <a class="header-anchor" href="#第一阶段-先让测试可重复" aria-label="Permalink to &quot;第一阶段：先让测试可重复&quot;">​</a></h3><ul><li>统一本地和 CI 测试命令；</li><li>建立最小单元和组件测试；</li><li>固定测试数据与依赖版本；</li><li>保存机器可读报告；</li><li>每个线上缺陷补回归测试。</li></ul><h3 id="第二阶段-建立测试机和发布证据" tabindex="-1">第二阶段：建立测试机和发布证据 <a class="header-anchor" href="#第二阶段-建立测试机和发布证据" aria-label="Permalink to &quot;第二阶段：建立测试机和发布证据&quot;">​</a></h3><ul><li>建立 Windows、Linux、Docker 测试基线；</li><li>自动部署候选制品；</li><li>执行安装、升级、冒烟和回滚；</li><li>记录环境、制品和测试结果；</li><li>对接口建立版本组合与契约测试。</li></ul><h3 id="第三阶段-覆盖真实风险" tabindex="-1">第三阶段：覆盖真实风险 <a class="header-anchor" href="#第三阶段-覆盖真实风险" aria-label="Permalink to &quot;第三阶段：覆盖真实风险&quot;">​</a></h3><ul><li>性能、长稳和故障注入；</li><li>SIL/HIL 与网络损伤测试；</li><li>安全测试和漏洞回归；</li><li>需求、风险和测试双向追溯；</li><li>发布前形成正式测试结论。</li></ul><h3 id="第四阶段-用数据改善测试体系" tabindex="-1">第四阶段：用数据改善测试体系 <a class="header-anchor" href="#第四阶段-用数据改善测试体系" aria-label="Permalink to &quot;第四阶段：用数据改善测试体系&quot;">​</a></h3><ul><li>统计缺陷逃逸、不稳定测试和定位时间；</li><li>找出最常出事故但最少测试的区域；</li><li>删除没有价值、长期重复的测试；</li><li>把事故原因变成新的自动检查或验证场景；</li><li>定期演练恢复，而不是只验证正常路径。</li></ul><hr><h2 id="_21-发布前检查清单" tabindex="-1">21. 发布前检查清单 <a class="header-anchor" href="#_21-发布前检查清单" aria-label="Permalink to &quot;21. 发布前检查清单&quot;">​</a></h2><h3 id="范围与风险" tabindex="-1">范围与风险 <a class="header-anchor" href="#范围与风险" aria-label="Permalink to &quot;范围与风险&quot;">​</a></h3><ul><li>[ ] 本次变更影响的功能、接口、数据、平台和设备已经列出。</li><li>[ ] 高风险失败模式都有明确测试方法。</li><li>[ ] 新旧版本组合和回滚兼容性已经考虑。</li></ul><h3 id="环境与数据" tabindex="-1">环境与数据 <a class="header-anchor" href="#环境与数据" aria-label="Permalink to &quot;环境与数据&quot;">​</a></h3><ul><li>[ ] 测试环境、设备、仪器、固件和配置版本已记录。</li><li>[ ] 测试数据来源、版本和隐私处理明确。</li><li>[ ] 关键测量使用独立、经过确认的工具或设备。</li></ul><h3 id="执行与证据" tabindex="-1">执行与证据 <a class="header-anchor" href="#执行与证据" aria-label="Permalink to &quot;执行与证据&quot;">​</a></h3><ul><li>[ ] 快、中、慢测试按发布级别完成。</li><li>[ ] 失败、跳过、重试和不稳定用例没有被隐藏。</li><li>[ ] 原始日志、测量数据、报告和制品摘要可以互相追溯。</li><li>[ ] 安装、升级、故障和恢复路径已经验证。</li></ul><h3 id="发布决定" tabindex="-1">发布决定 <a class="header-anchor" href="#发布决定" aria-label="Permalink to &quot;发布决定&quot;">​</a></h3><ul><li>[ ] 已写明没有测试的范围和剩余风险。</li><li>[ ] 灰度、观察指标、停止条件和恢复目标明确。</li><li>[ ] 医疗/机器人版本确认处于允许更新的窗口，现场接管可用。</li></ul><hr><h2 id="_22-参考资料" tabindex="-1">22. 参考资料 <a class="header-anchor" href="#_22-参考资料" aria-label="Permalink to &quot;22. 参考资料&quot;">​</a></h2><ul><li><a href="https://sre.google/sre-book/testing-reliability/" target="_blank" rel="noreferrer">Google SRE：Testing for Reliability</a></li><li><a href="https://cmake.org/cmake/help/latest/manual/ctest.1.html" target="_blank" rel="noreferrer">CMake：CTest 官方文档</a></li><li><a href="https://testcontainers.com/getting-started/" target="_blank" rel="noreferrer">Testcontainers：Getting Started</a></li><li><a href="https://owasp.org/www-project-application-security-verification-standard/" target="_blank" rel="noreferrer">OWASP Application Security Verification Standard</a></li><li><a href="https://csrc.nist.gov/pubs/sp/800/218/final" target="_blank" rel="noreferrer">NIST SP 800-218：Secure Software Development Framework</a></li><li><a href="https://www.ccfdie.org/cn/yjxx/ylqx/webinfo/2022/03/1648289422626166.htm" target="_blank" rel="noreferrer">医疗器械网络安全注册审查指导原则（2022 年修订版）</a></li></ul><blockquote><p>具体医疗器械标准、软件安全性级别、测试次数和注册证据要求，应由质量与法规团队结合产品分类、预期用途、风险管理和最新监管沟通正式确认。本手册用于建立工程方法，不替代适用标准和法规判断。</p></blockquote>',260)])])}const E=s(b,[["render",u]]);export{_ as __pageData,E as default};
